#!/usr/bin/env node
// tools/genref/render-site.mjs -- assemble the public Pages artifact:
// a hand-authored landing page, HTML renderings of the generated reference
// (docs/reference) and the guides (docs/guides), the repository README, the
// third-party notices generated by the dependency/license closure
// (tools/sbom/), and optionally the static export of the real frontend.
//
//   node tools/genref/render-site.mjs --out DIR [--app DIST_CLIENT_DIR] \
//        [--repo-url URL]
//
// Zero dependencies, deliberately: the gen-1 microsite's discipline was "no
// build step, no external asset or network dependency", and this keeps it.
// The Markdown converter below covers exactly the constructs the reference
// generator emits and the guides use (headings, paragraphs, lists with
// continuations, tables with escaped pipes, fenced code, blockquotes, inline
// code/bold/italic/links). Anything else passes through as escaped text --
// visible, never dropped. Every rendered page is link-checked at the end:
// a relative link must resolve inside the artifact, and a link to a
// repository file that is not part of the site is rewritten to the
// repository URL instead of being left to 404.
//
// The artifact's layout -- THE APP IS THE SITE, and the documentation is a
// section of it:
//   index.html            the app's own landing (apps/dclutch-web app/page.tsx)
//   markets.html, create.html, trade.html, …   the app's other routes
//   _next/…               the app's assets
//   404.html              the app's not-found shell, which also resolves the
//                          dynamic routes the export cannot prerender
//   evidence.html         the run-evidence index, at the URL a filed public
//                          comment cites
//   docs/index.html       the documentation landing (authored in this file)
//   docs/readme.html      the repository README, rendered
//   docs/reference/…      docs/reference rendered (same tree shape)
//   docs/guides/…         docs/guides rendered
//   docs/notices.html     tools/sbom/NOTICES.md rendered (third-party
//                          notices, generated by tools/sbom/sbom_check.py)
//   docs/style.css        one stylesheet, for the rendered pages
//
// Why the app owns the root. The export emits ROOT-ABSOLUTE URLs for both its
// assets (`/_next/…`) and its own navigation (`/markets`, `/create`), and
// The domain-root mount was established against vinext 1.0.0-beta.3. The
// artifact-level invariant below remains version-independent: assets and app
// routes must resolve together at the URLs the export emitted.
//
//   - `basePath` is incompatible with output:'export' -- its export
//     prerenderer requests un-prefixed paths and skips every route;
//   - `assetPrefix` alone DOES survive the export (measured 2026-08-27: it
//     emits `/app/_next/…` and relocates the on-disk directory to match), but
//     it moves assets only. Every in-app link would still point at the domain
//     root and 404. A styled page whose every link is broken is not a fix.
//
// So the app is mounted where its URLs already say it is. Mounting it under
// /app/ was what served raw unstyled HTML on the live site: the pages carried
// `/_next/…` while the assets sat at `/app/_next/…`, and no workspace ever
// hydrated. The documentation moves to /docs/ instead, where a relative-linked
// static tree is happy at any depth.
//
// The link check below covers the app's pages TOO, resolving root-absolute
// targets against the artifact root. Skipping them is exactly how the /app/
// breakage passed a green link check.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(HERE, "..", "..");

const argv = process.argv.slice(2);
let outDir = null;
let appDir = null;
let repoUrl = "https://github.com/emberian/dragons-clutch/blob/main/dclutch";
for (let i = 0; i < argv.length; i++) {
  if (argv[i] === "--out") outDir = argv[++i];
  else if (argv[i] === "--app") appDir = argv[++i];
  else if (argv[i] === "--repo-url") repoUrl = argv[++i];
  else {
    console.error(`render-site: unknown argument ${argv[i]}`);
    process.exit(2);
  }
}
if (!outDir) {
  console.error("render-site: --out DIR is required");
  process.exit(2);
}
outDir = path.resolve(outDir);

// The subdirectory the rendered documentation is mounted at. The app owns the
// artifact root (see the header), so every rendered page lives under this and
// links to its siblings relatively -- the tree is position-independent. The
// app links INTO it through NEXT_PUBLIC_DCLUTCH_DOCS_BASE, which the Pages
// workflow sets to the same value with a leading slash.
const DOCS = "docs";

// ----------------------------------------------------------- what we render

// repo-relative .md -> site-relative .html
const renderSet = new Map();
renderSet.set("README.md", "readme.html");
renderSet.set("tools/sbom/NOTICES.md", "notices.html");
{
  const walk = (dir) => {
    for (const e of fs.readdirSync(path.join(REPO, dir)).sort()) {
      const rel = path.posix.join(dir, e);
      const abs = path.join(REPO, rel);
      if (fs.statSync(abs).isDirectory()) walk(rel);
      else if (e.endsWith(".md")) {
        renderSet.set(
          rel,
          rel.replace(/^docs\//, "").replace(/\.md$/, ".html"),
        );
      }
    }
  };
  walk("docs/guides");
  // The run evidence renders too. A filed public comment cites the Evidence
  // page by URL, so these documents have to be readable on the site and not
  // only in the repository -- see the `/evidence` index below.
  walk("docs/evidence");
}
// The generated reference is rendered selectively. Error meanings and byte
// layouts are the reference a client developer actually needs, so they stay
// on the site; the other generated ledgers (routes, budgets, decisions,
// programs) live complete in the repository, and any link to them from a
// rendered page is rewritten to point there.
renderSet.set("docs/reference/refusals.md", "reference/refusals.html");
for (const e of fs
  .readdirSync(path.join(REPO, "docs", "reference", "abi"))
  .sort()) {
  if (e.endsWith(".md")) {
    renderSet.set(
      `docs/reference/abi/${e}`,
      `reference/abi/${e.replace(/\.md$/, ".html")}`,
    );
  }
}

// --------------------------------------------------------------- inline md

function escapeHtml(s) {
  return s
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

// Resolve a Markdown link target found in sourceRel (repo-relative md path)
// into an href usable from that page's rendered location.
function resolveHref(target, sourceRel) {
  if (/^[a-z][a-z0-9+.-]*:/.test(target) || target.startsWith("#")) {
    return target; // absolute URL or fragment
  }
  const [pathPart, frag] = target.split("#");
  const sourceDirRepo = path.posix.dirname(sourceRel);
  const resolvedRepo = path.posix.normalize(
    path.posix.join(sourceDirRepo, pathPart),
  );
  const suffix = frag ? `#${frag}` : "";
  if (renderSet.has(resolvedRepo)) {
    const fromDir = path.posix.dirname(renderSet.get(sourceRel));
    const to = renderSet.get(resolvedRepo);
    return path.posix.relative(fromDir, to) + suffix;
  }
  // Not part of the site: send the reader to the repository.
  return `${repoUrl}/${resolvedRepo}${suffix}`;
}

function inlineMd(text, sourceRel) {
  // Tokenize inline code into placeholders first, so nothing inside
  // backticks is styled AND so bold/link syntax that *contains* a code span
  // still pairs up across it ("**`X` -- title.**", "[`doc.md`](doc.md)").
  const codes = [];
  let s = text.replace(/`([^`]*)`/g, (_m, c) => {
    codes.push(`<code>${escapeHtml(c)}</code>`);
    return `\u0000${codes.length - 1}\u0000`;
  });
  s = escapeHtml(s);
  // links: [text](target)
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_m, txt, href) => {
    return `<a href="${resolveHref(href, sourceRel)}">${txt}</a>`;
  });
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/(^|[\s(])\*([^*\s][^*]*)\*(?=[\s).,;:!?]|$)/g, "$1<em>$2</em>");
  s = s.replace(/\u0000(\d+)\u0000/g, (_m, idx) => codes[Number(idx)]);
  return s;
}

// Split a table row on unescaped pipes; unescape \| inside cells.
function splitRow(line) {
  const cells = [];
  let cur = "";
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === "\\" && line[i + 1] === "|") {
      cur += "|";
      i++;
    } else if (c === "|") {
      cells.push(cur);
      cur = "";
    } else {
      cur += c;
    }
  }
  cells.push(cur);
  // leading/trailing empties from the outer pipes
  if (cells.length && cells[0].trim() === "") cells.shift();
  if (cells.length && cells[cells.length - 1].trim() === "") cells.pop();
  return cells.map((c) => c.trim());
}

// ---------------------------------------------------------------- block md

function mdToHtml(md, sourceRel) {
  const lines = md.split("\n");
  const out = [];
  let i = 0;
  // Skip a leading HTML comment block (the @generated header).
  while (i < lines.length && lines[i].trim() === "") i++;
  if (i < lines.length && lines[i].startsWith("<!--")) {
    while (i < lines.length && !lines[i].includes("-->")) i++;
    i++;
  }

  const isTableSep = (l) => /^\|?[\s:|-]+\|?$/.test(l) && l.includes("-");

  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === "") {
      i++;
      continue;
    }
    // fenced code
    if (line.startsWith("```")) {
      const buf = [];
      i++;
      while (i < lines.length && !lines[i].startsWith("```")) {
        buf.push(lines[i]);
        i++;
      }
      i++; // closing fence
      out.push(`<pre><code>${escapeHtml(buf.join("\n"))}</code></pre>`);
      continue;
    }
    // heading
    const h = line.match(/^(#{1,6}) (.*)$/);
    if (h) {
      const level = h[1].length;
      const text = inlineMd(h[2], sourceRel);
      const id = h[2]
        .toLowerCase()
        .replace(/`/g, "")
        .replace(/[^a-z0-9\s-]/g, "")
        .trim()
        .replace(/\s+/g, "-");
      out.push(`<h${level} id="${id}">${text}</h${level}>`);
      i++;
      continue;
    }
    // table
    if (line.startsWith("|") && i + 1 < lines.length && isTableSep(lines[i + 1])) {
      const headers = splitRow(line);
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].startsWith("|")) {
        rows.push(splitRow(lines[i]));
        i++;
      }
      const th = headers
        .map((c) => `<th>${inlineMd(c, sourceRel)}</th>`)
        .join("");
      const trs = rows
        .map(
          (r) =>
            `<tr>${r.map((c) => `<td>${inlineMd(c, sourceRel)}</td>`).join("")}</tr>`,
        )
        .join("\n");
      out.push(
        `<div class="tablewrap"><table><thead><tr>${th}</tr></thead><tbody>\n${trs}\n</tbody></table></div>`,
      );
      continue;
    }
    // blockquote
    if (line.startsWith(">")) {
      const buf = [];
      while (i < lines.length && lines[i].startsWith(">")) {
        buf.push(lines[i].replace(/^> ?/, ""));
        i++;
      }
      out.push(
        `<blockquote>${mdToHtml(buf.join("\n"), sourceRel)}</blockquote>`,
      );
      continue;
    }
    // list (unordered or ordered), items may have indented continuations
    const listStart = line.match(/^(-|\d+\.) /);
    if (listStart) {
      const ordered = listStart[1] !== "-";
      const items = [];
      while (i < lines.length) {
        const m = lines[i].match(/^(-|\d+\.) (.*)$/);
        if (!m) break;
        const item = [m[2]];
        i++;
        while (
          i < lines.length &&
          (lines[i].match(/^\s+\S/) || lines[i].trim() === "")
        ) {
          if (lines[i].trim() === "") {
            // blank inside a list ends it only if the next line is not indented
            if (!(i + 1 < lines.length && lines[i + 1].match(/^\s+\S/))) break;
            item.push("");
          } else {
            item.push(lines[i].trim());
          }
          i++;
        }
        items.push(item.join(" ").replace(/\s{2,}/g, " ").trim());
      }
      const tag = ordered ? "ol" : "ul";
      out.push(
        `<${tag}>\n${items
          .map((it) => `<li>${inlineMd(it, sourceRel)}</li>`)
          .join("\n")}\n</${tag}>`,
      );
      continue;
    }
    // paragraph: join until blank/structural line
    const buf = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !lines[i].startsWith("#") &&
      !lines[i].startsWith("```") &&
      !lines[i].startsWith("|") &&
      !lines[i].startsWith(">") &&
      !lines[i].match(/^(-|\d+\.) /)
    ) {
      buf.push(lines[i]);
      i++;
    }
    out.push(`<p>${inlineMd(buf.join(" "), sourceRel)}</p>`);
  }
  return out.join("\n");
}

// ------------------------------------------------------------------ chrome

const STYLE = `:root { color-scheme: light dark;
  --bg: #ffffff; --fg: #1a1d21; --muted: #5c6570; --line: #d9dee3;
  --code-bg: #f2f4f6; --accent: #7a4dbe; --warn-bg: #fff7e6; --warn-line: #e8c576; }
@media (prefers-color-scheme: dark) { :root {
  --bg: #14161a; --fg: #e6e4df; --muted: #98a0a8; --line: #2c3138;
  --code-bg: #1d2126; --accent: #b394e6; --warn-bg: #2a2415; --warn-line: #6d5a2a; } }
* { box-sizing: border-box; }
body { background: var(--bg); color: var(--fg); margin: 0;
  font: 16px/1.6 -apple-system, "Segoe UI", system-ui, sans-serif; }
main { max-width: 46rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
h1, h2, h3, h4 { line-height: 1.25; margin: 1.8em 0 0.5em; }
h1 { margin-top: 0.4em; }
a { color: var(--accent); }
code { background: var(--code-bg); padding: 0.1em 0.35em; border-radius: 4px;
  font: 0.875em/1.5 ui-monospace, "SF Mono", Menlo, monospace; }
pre { background: var(--code-bg); padding: 0.9rem 1rem; border-radius: 8px;
  overflow-x: auto; }
pre code { background: none; padding: 0; font-size: 0.8125rem; }
.tablewrap { overflow-x: auto; margin: 1rem 0; }
table { border-collapse: collapse; font-size: 0.875rem; min-width: 100%; }
th, td { border: 1px solid var(--line); padding: 0.35rem 0.6rem;
  text-align: left; vertical-align: top; }
th { background: var(--code-bg); }
blockquote { border-left: 3px solid var(--line); margin: 1rem 0;
  padding: 0.1rem 0 0.1rem 1rem; color: var(--muted); }
nav.crumbs { font-size: 0.875rem; color: var(--muted); margin-bottom: 1.5rem; }
nav.crumbs a { color: var(--muted); }
.unreleased { background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 8px; padding: 0.75rem 1rem; font-size: 0.9375rem;
  margin: 1.25rem 0; }
footer { max-width: 46rem; margin: 0 auto; padding: 0 1.25rem 2.5rem;
  color: var(--muted); font-size: 0.8125rem; border-top: 1px solid var(--line);
  padding-top: 1rem; }
.cards { display: grid; gap: 0.9rem; grid-template-columns:
  repeat(auto-fit, minmax(15rem, 1fr)); margin: 1.5rem 0; padding: 0; }
.cards li { list-style: none; border: 1px solid var(--line); border-radius: 8px;
  padding: 0.9rem 1rem; }
.cards li strong { display: block; margin-bottom: 0.25rem; }
`;

// `depth` counts directories below the DOCS root, which is where style.css
// lives. `style` overrides that for the one page written outside it (the
// no-app placeholder at the artifact root).
function page({ title, body, depth, crumbs, style }) {
  const root = "../".repeat(depth);
  const styleHref = style ?? `${root}style.css`;
  const crumbHtml = crumbs
    ? `<nav class="crumbs">${crumbs}</nav>`
    : `<nav class="crumbs"><a href="${root}index.html">dClutch</a></nav>`;
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<link rel="stylesheet" href="${styleHref}">
</head>
<body>
<main>
${crumbHtml}
${body}
</main>
<footer>dClutch has seven programs on Solana devnet. There is no open market,
no value at risk, and nothing to buy. This is not a mainnet release.
<a href="${repoUrl.replace(/\/blob\/.*$/, "")}">Repository</a>.</footer>
</body>
</html>
`;
}

// The documentation landing, at docs/index.html. This page is the section's
// own front door and states the deployed devnet boundary without turning it
// into a mainnet or open-market claim.
const DOCS_BODY = `<h1>dClutch documentation</h1>
<p>Everything below is generated from, or lives beside, the code it
describes. dClutch is a Solana protocol for markets on real-world numbers:
you buy claims on the outcome you believe in, and every claim is fully
backed by collateral locked up before the claim exists.</p>
<div class="unreleased"><strong>Devnet preview.</strong> The seven programs
are deployed on Solana devnet. There is no open market, no value at risk, and
nothing to buy today. Devnet and local test-chain runs are not mainnet
evidence.</div>
<ul class="cards">
<li><strong><a href="guides/README.html">Guides</a></strong>
Start here: what a claim is, how protection works, how to run a market,
how to build your own client -- and how to try the whole thing
yourself.</li>
<li><strong><a href="readme.html">The README</a></strong>
The project at a glance: what works today, the seven programs, and where
it's going.</li>
<li><strong>For developers</strong>
<a href="reference/refusals.html">Every error code with its meaning</a> and
<a href="reference/abi/README.html">the exact byte layouts</a>, generated
from the code. The rest of the generated reference lives in the
<a href="${repoUrl}/docs/reference/README.md">repository</a>.</li>
<li><strong><a href="../evidence.html">Evidence</a></strong>
The write-up of every run behind a claim on this site: what was executed,
against which chain or harness, and what it did not establish.</li>
<li><strong><a href="notices.html">Third-party notices</a></strong>
The licenses of everything this project ships.</li>
</ul>
<p>Building on it? The tests and run logs behind every claim on this site
live in the <a href="${repoUrl.replace(/\/blob\/.*$/, "")}">repository</a>.</p>
`;

// Stands in at the artifact root when --app was not passed. The app owns the
// root now, so without it the site has no front door at all.
const NO_APP_BODY = `<h1>Application not included</h1>
<p>This artifact was assembled without the frontend's static export
(<code>render-site.mjs</code> ran without <code>--app</code>), and the app is
what the site root serves. Build it with <code>DCLUTCH_PAGES_EXPORT=1 npm run
build</code> in <code>apps/dclutch-web</code> and pass <code>--app
apps/dclutch-web/dist/client</code>.</p>
<p>The rendered documentation was assembled and is
<a href="${DOCS}/index.html">here</a>.</p>`;

// ------------------------------------------------------------------- build

fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

// The app first, at the root: its own index.html is the site's front door.
if (appDir) {
  const src = path.resolve(appDir);
  if (!fs.existsSync(path.join(src, "index.html"))) {
    console.error(
      `render-site: --app ${appDir} has no index.html (build the export first)`,
    );
    process.exit(1);
  }
  fs.cpSync(src, outDir, { recursive: true });
}

// Then the documentation, under docs/.
const docsDir = path.join(outDir, DOCS);
fs.mkdirSync(docsDir, { recursive: true });
fs.writeFileSync(path.join(docsDir, "style.css"), STYLE);

const titles = new Map(); // siteRel -> title
for (const [src, dst] of renderSet) {
  const md = fs.readFileSync(path.join(REPO, src), "utf8");
  const m = md.match(/^# (.*)$/m);
  titles.set(dst, m ? m[1].replace(/`/g, "") : dst);
}

for (const [src, dst] of renderSet) {
  const md = fs.readFileSync(path.join(REPO, src), "utf8");
  const body = mdToHtml(md, src);
  const depth = dst.split("/").length - 1;
  const html = page({ title: `${titles.get(dst)} - dClutch`, body, depth });
  const p = path.join(docsDir, dst);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, html);
}

fs.writeFileSync(
  path.join(docsDir, "index.html"),
  page({
    title: "dClutch documentation",
    body: DOCS_BODY,
    depth: 0,
    crumbs: `<a href="../index.html">dClutch</a>`,
  }),
);

// ------------------------------------------------------- the evidence index
//
// `/evidence` at the artifact ROOT, which is otherwise the app's alone.
//
// A filed public comment cites "the explanation's Evidence page" by that URL.
// A citation in a public record is not a thing this repository gets to move,
// so the page is written where the citation points. It is the one document
// rendered beside the app instead of under `docs/`, and this comment is the
// reason it is allowed to be.
//
// The list is GENERATED from what actually rendered out of `docs/evidence/`.
// A hand-kept index on a page a regulator may open is an index that drifts,
// and a stale one here would be a claim about what was run.
{
  const evidence = [...renderSet]
    .filter(([src]) => src.startsWith("docs/evidence/"))
    .map(([, dst]) => dst)
    .sort();
  if (evidence.length === 0) {
    console.error(
      "render-site: docs/evidence rendered no documents, but /evidence is a " +
        "cited URL; refusing the artifact.",
    );
    process.exit(1);
  }
  const target = path.join(outDir, "evidence.html");
  if (fs.existsSync(target)) {
    // The app grew a route of its own here. Two pages cannot answer one cited
    // URL; decide which, rather than letting a copy order decide.
    console.error(
      "render-site: the app export already provides evidence.html and this " +
        "would overwrite it; refusing the artifact.",
    );
    process.exit(1);
  }
  const items = evidence
    .map(
      (dst) =>
        `<li><strong><a href="${DOCS}/${dst}">${escapeHtml(titles.get(dst))}</a></strong></li>`,
    )
    .join("\n");
  fs.writeFileSync(
    target,
    page({
      title: "Evidence - dClutch",
      depth: 0,
      crumbs: `<a href="index.html">dClutch</a>`,
      style: `${DOCS}/style.css`,
      body: `<h1>Evidence</h1>
<p>Every document below is the write-up of a run that happened: what was
executed, against which chain or harness, and what it produced. They are
kept beside the code they were run against, and each one states its own
scope -- including what it did <em>not</em> establish.</p>
<div class="unreleased"><strong>Not live yet.</strong> dClutch is not
deployed on any network. These runs were made on local test chains and in
test harnesses. A run here is evidence about software, not about a
deployment, and none of it is an offer of anything.</div>
<ul class="cards">
${items}
</ul>
<p>The raw artifacts each document cites -- transcripts, images, JSON --
live beside it in the
<a href="${repoUrl}/docs/evidence/">repository</a>.</p>`,
    }),
  );
}

if (!appDir) {
  fs.writeFileSync(
    path.join(outDir, "index.html"),
    page({
      title: "dClutch",
      body: NO_APP_BODY,
      depth: 0,
      crumbs: "&nbsp;",
      style: `${DOCS}/style.css`,
    }),
  );
}

// -------------------------------------------------------------- link check
//
// Every page in the artifact, the app's included -- the app was skipped here
// before, which is how a site whose every stylesheet and script 404'd passed
// this check green.
//
// Two resolution rules the app's pages need and the rendered pages do not:
// a target beginning with "/" resolves against the ARTIFACT ROOT (that is
// exactly the invariant the mount has to honor), and an extensionless target
// is served by GitHub Pages from "<target>.html" or "<target>/index.html", so
// either satisfies it. Anything a static host cannot answer is broken.

let broken = 0;
const walkOut = (dir, acc = []) => {
  for (const e of fs.readdirSync(dir).sort()) {
    const p = path.join(dir, e);
    if (fs.statSync(p).isDirectory()) walkOut(p, acc);
    else acc.push(p);
  }
  return acc;
};

const isFile = (p) => fs.existsSync(p) && fs.statSync(p).isFile();

/** What GitHub Pages would serve for one in-artifact path, or null. */
function servedBy(abs) {
  if (isFile(abs)) return abs;
  if (isFile(`${abs}.html`)) return `${abs}.html`;
  if (isFile(path.join(abs, "index.html"))) return path.join(abs, "index.html");
  return null;
}

// Routes the export declares dynamic: `/markets/:address` is rendered from a
// path parameter, so no prerendered file exists and no href in a STATIC page
// can name one. If one ever does, this list is the place to justify it.
//
// These are not broken links. The host answers them with 404.html, which the
// app builds (app/not-found.tsx) as a shell that reads location.pathname and
// renders the route it names -- `apps/dclutch-web/lib/exportRouting.ts` holds
// the same list on the app's side. A new dynamic route belongs in both.
const DYNAMIC_PREFIXES = ["/markets/"];

let checkedPages = 0;
for (const file of walkOut(outDir)) {
  if (!file.endsWith(".html")) continue;
  checkedPages++;
  const html = fs.readFileSync(file, "utf8");
  for (const m of html.matchAll(/(?:href|src)="([^"]+)"/g)) {
    const target = m[1];
    // absolute URL, protocol-relative, fragment, or an empty href
    if (/^[a-z][a-z0-9+.-]*:/.test(target)) continue;
    if (target.startsWith("//") || target.startsWith("#") || target === "") {
      continue;
    }
    const pathPart = target.split("#")[0].split("?")[0];
    if (pathPart === "") continue;
    if (DYNAMIC_PREFIXES.some((p) => pathPart.startsWith(p))) continue;
    const abs = pathPart.startsWith("/")
      ? path.join(outDir, pathPart)
      : path.resolve(path.dirname(file), pathPart);
    if (servedBy(abs) === null) {
      console.error(
        `render-site: BROKEN LINK ${path.relative(outDir, file)} -> ${target}`,
      );
      broken++;
    }
  }
}
if (broken > 0) {
  console.error(`render-site: ${broken} broken link(s); refusing the artifact.`);
  process.exit(1);
}

// The mount's own invariant, stated once instead of inferred from the links:
// the app's front door is the artifact's, its assets sit where its pages say
// they do, and its 404 document exists -- that last one because 404.html is
// what a static host serves for `/markets/<address>`, the app's one dynamic
// route, and the app builds it (app/not-found.tsx) as a shell that resolves
// the path client-side. Without it a shared permalink is a dead end again.
if (appDir) {
  for (const required of [
    "index.html",
    "404.html",
    path.join("_next", "static"),
  ]) {
    if (!fs.existsSync(path.join(outDir, required))) {
      console.error(
        `render-site: the app export is mounted at the root but ${required} is missing; refusing the artifact.`,
      );
      process.exit(1);
    }
  }
}

console.log(
  `render-site: wrote ${walkOut(outDir).length} files to ${outDir} ` +
    `(${renderSet.size} pages rendered under ${DOCS}/, ` +
    `${checkedPages} pages link-checked${appDir ? ", app mounted at the root" : ", NO app"}).`,
);
